<?php
require_once 'includes/config.php'; require_once 'includes/phase1.php'; require_once 'includes/phase3.php'; require_teacher(); $tid=current_teacher_id();
$studentId=(int)($_GET['student_id']??$_POST['student_id']??0); $classId=(int)($_GET['class_id']??$_POST['class_id']??0);
if(!$studentId||!$classId||!teacher_can_grade($dbh,$tid,$studentId,$classId)){http_response_code(403);exit('You are not assigned to this student and class.');}
$s=$dbh->prepare('SELECT s.StudentId,s.StudentName,s.RollId,c.ClassName,c.Section FROM tblstudents s JOIN tblclasses c ON c.id=s.ClassId WHERE s.StudentId=:s AND s.ClassId=:c LIMIT 1');$s->execute([':s'=>$studentId,':c'=>$classId]);$student=$s->fetch();
$year=trim($_POST['academic_year']??date('Y').'/'.(date('Y')+1));$term=trim($_POST['term']??'Final');$exam=trim($_POST['exam_type']??'Final Examination');$msg='';$error='';
$sub=$dbh->prepare('SELECT sc.SubjectId,sub.SubjectName FROM tblsubjectcombination sc JOIN tblsubjects sub ON sub.id=sc.SubjectId WHERE sc.ClassId=:c AND sc.status=1 ORDER BY sub.SubjectName');$sub->execute([':c'=>$classId]);$subjects=$sub->fetchAll();
$existing=[];$rsq=$dbh->prepare('SELECT * FROM tblresult WHERE StudentId=:s AND ClassId=:c AND AcademicYear=:y AND Term=:t AND ExamType=:e');$rsq->execute([':s'=>$studentId,':c'=>$classId,':y'=>$year,':t'=>$term,':e'=>$exam]);foreach($rsq as $r)$existing[(int)$r['SubjectId']]=$r;
$submissionQ=$dbh->prepare('SELECT * FROM result_submissions WHERE teacher_id=:t AND student_id=:s AND class_id=:c AND academic_year=:y AND term=:term AND exam_type=:e LIMIT 1');$submissionQ->execute([':t'=>$tid,':s'=>$studentId,':c'=>$classId,':y'=>$year,':term'=>$term,':e'=>$exam]);$submission=$submissionQ->fetch();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save'])){
    $marks=$_POST['marks']??[]; if(!is_array($marks)||count($marks)!==count($subjects))$error='Please enter a mark for every subject.';
    elseif($submission && $submission['submission_status']==='pending')$error='This result is already submitted and is waiting for administrator review.';
    elseif($submission && $submission['submission_status']!=='rework')$error='This result is locked. An administrator must return it for rework before you can edit it.';
    else { try{ period_ensure($dbh,$year,$term,$exam); period_require_unlocked($dbh,$year,$term,$exam); $dbh->beginTransaction();
        if($submission && $submission['submission_status']==='rework'){$upd=$dbh->prepare("UPDATE result_submissions SET submission_status='rework',approval_state='pending',rejection_reason=NULL,updated_at=NOW() WHERE id=:id");$upd->execute([':id'=>$submission['id']]);$submissionId=(int)$submission['id'];}
        else {$ins=$dbh->prepare("INSERT INTO result_submissions(teacher_id,student_id,class_id,academic_year,term,exam_type,submission_status,approval_state) VALUES(:t,:s,:c,:y,:term,:e,'rework','pending') ON DUPLICATE KEY UPDATE updated_at=NOW()");$ins->execute([':t'=>$tid,':s'=>$studentId,':c'=>$classId,':y'=>$year,':term'=>$term,':e'=>$exam]);$sq=$dbh->prepare('SELECT id FROM result_submissions WHERE teacher_id=:t AND student_id=:s AND class_id=:c AND academic_year=:y AND term=:term AND exam_type=:e');$sq->execute([':t'=>$tid,':s'=>$studentId,':c'=>$classId,':y'=>$year,':term'=>$term,':e'=>$exam]);$submissionId=(int)$sq->fetchColumn();}
        foreach($subjects as $i=>$subject){$mark=filter_var($marks[$i],FILTER_VALIDATE_INT,['options'=>['min_range'=>0,'max_range'=>100]]);if($mark===false)throw new RuntimeException('Marks must be whole numbers from 0 to 100.');
            $q=$dbh->prepare('SELECT id FROM tblresult WHERE StudentId=:s AND ClassId=:c AND SubjectId=:sub AND AcademicYear=:y AND Term=:term AND ExamType=:e LIMIT 1');$q->execute([':s'=>$studentId,':c'=>$classId,':sub'=>$subject['SubjectId'],':y'=>$year,':term'=>$term,':e'=>$exam]);$id=$q->fetchColumn();
            if($id){snapshot_result($dbh,(int)$id,'teacher',$tid,'TEACHER_EDIT','Teacher edited result');$u=$dbh->prepare("UPDATE tblresult SET marks=:m,teacher_id=:t,submission_id=:sid,result_status='rework',approval_state='pending',Published=0,published_by=NULL,published_at=NULL,UpdationDate=NOW() WHERE id=:id");$u->execute([':m'=>$mark,':t'=>$tid,':sid'=>$submissionId,':id'=>$id]);}
            else{$u=$dbh->prepare("INSERT INTO tblresult(StudentId,ClassId,SubjectId,teacher_id,submission_id,marks,AcademicYear,Term,ExamType,MaxMarks,Published,result_status,approval_state) VALUES(:s,:c,:sub,:t,:sid,:m,:y,:term,:e,100,0,'rework','pending')");$u->execute([':s'=>$studentId,':c'=>$classId,':sub'=>$subject['SubjectId'],':t'=>$tid,':sid'=>$submissionId,':m'=>$mark,':y'=>$year,':term'=>$term,':e'=>$exam]);}
        }
        $dbh->commit();audit_log($dbh,'RESULT_DRAFT_SAVE','Teacher '.$tid.' saved marks for student '.$studentId.' / '.$year.' / '.$term.' / '.$exam);$msg='Draft saved. Use Submit for Review when the marks are complete.';$submissionQ->execute([':t'=>$tid,':s'=>$studentId,':c'=>$classId,':y'=>$year,':term'=>$term,':e'=>$exam]);$submission=$submissionQ->fetch();
    }catch(Throwable $ex){if($dbh->inTransaction())$dbh->rollBack();$error=$ex->getMessage();}}
}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['submit_review'])){
    if($submission && in_array($submission['submission_status'],['pending','approved'],true))$error='This result cannot be submitted in its current state.';
    else { $dbh->beginTransaction(); try{$q=$dbh->prepare("UPDATE result_submissions SET submission_status='pending',approval_state='pending',submitted_at=NOW(),updated_at=NOW(),rejection_reason=NULL WHERE id=:id AND teacher_id=:t");$q->execute([':id'=>$submission['id']??0,':t'=>$tid]);$q2=$dbh->prepare("UPDATE tblresult SET result_status='submitted',approval_state='pending',Published=0,UpdationDate=NOW() WHERE submission_id=:sid");$q2->execute([':sid'=>$submission['id']]);$dbh->commit();audit_log($dbh,'RESULT_SUBMITTED','Submission '.$submission['id'].' sent for review'); notify_all_admins($dbh,'New result submitted','Teacher '.$_SESSION['teacher_name'].' submitted results for '.$student['StudentName'].' ('.$year.' / '.$term.' / '.$exam.') for review.','info','result-approvals.php'); $msg='Result submitted to the administrator for review.';$submissionQ->execute([':t'=>$tid,':s'=>$studentId,':c'=>$classId,':y'=>$year,':term'=>$term,':e'=>$exam]);$submission=$submissionQ->fetch();}catch(Throwable $ex){if($dbh->inTransaction())$dbh->rollBack();$error=$ex->getMessage();}}
}
$locked=$submission && in_array($submission['submission_status'],['pending','approved'],true);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grade Student | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body><nav class="navbar navbar-default srms-mobile-nav"><div class="container-fluid"><a class="navbar-brand" href="teacher-dashboard.php"><?php echo e(srms_school_name());?></a><p class="navbar-text pull-right"><img src="profile-photo.php?type=teacher&id=<?php echo (int)($_SESSION['teacher_id']??0);?>" alt="Profile photo" width="28" height="28" style="border-radius:50%;object-fit:cover" onerror="this.style.display='none'"> <?php echo e($_SESSION['teacher_name']??'Teacher');?> · <a href="teacher-logout.php">Sign out</a></p></div></nav><div class="container-fluid srms-page"><div class="srms-toolbar"><a class="btn btn-default" href="teacher-grades.php">← Back</a><a class="btn btn-danger pull-right" href="teacher-logout.php">Logout</a></div><div class="panel"><div class="panel-heading"><h3><?php echo e($student['StudentName']);?> <small><?php echo e($student['RollId'].' · '.$student['ClassName'].' '.$student['Section']);?></small></h3></div><div class="panel-body"><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?><?php if($submission && $submission['submission_status']==='rework'):?><div class="alert alert-warning"><strong>Returned for rework.</strong> <?php echo e($submission['rejection_reason']);?></div><?php endif;?><form method="post"><?php echo csrf_field();?><input type="hidden" name="student_id" value="<?php echo $studentId;?>"><input type="hidden" name="class_id" value="<?php echo $classId;?>"><div class="row"><div class="col-sm-4"><label>Academic Year</label><input class="form-control" name="academic_year" value="<?php echo e($year);?>" required <?php echo $locked?'readonly':'';?>></div><div class="col-sm-4"><label>Term</label><input class="form-control" name="term" value="<?php echo e($term);?>" required <?php echo $locked?'readonly':'';?>></div><div class="col-sm-4"><label>Examination</label><input class="form-control" name="exam_type" value="<?php echo e($exam);?>" required <?php echo $locked?'readonly':'';?>></div></div><hr><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Subject</th><th style="width:180px">Marks / 100</th></tr></thead><tbody><?php foreach($subjects as $i=>$subj):$val=$existing[(int)$subj['SubjectId']]['marks']??'';?><tr><td><?php echo e($subj['SubjectName']);?></td><td><input class="form-control" type="number" min="0" max="100" name="marks[]" value="<?php echo e($val);?>" required <?php echo $locked?'readonly':'';?>></td></tr><?php endforeach;?></tbody></table></div><?php if(!$locked):?><button class="btn btn-default" name="save">Save Draft</button><?php if($submission):?><button class="btn btn-primary" name="submit_review" value="1">Submit for Admin Review</button><?php endif;?><?php else:?><span class="label label-<?php echo $submission['submission_status']==='approved'?'success':'warning';?>"><?php echo e(result_status_label($submission['submission_status']));?></span><?php endif;?></form></div></div></div></body></html>
